import assert from "node:assert/strict";
import { test } from "node:test";
import { createApp } from "../../shared/http.ts";
import { MemoryStore } from "../../shared/storage.ts";
import { feature } from "../../features/reverse/index.ts";

async function call(value: unknown): Promise<{ status: number; result: unknown }> {
  const app = createApp([feature], new MemoryStore());
  const response = await app(new Request("http://app.test/reverse", { method: "POST", body: JSON.stringify({ value }), headers: { "content-type": "application/json" } }));
  const body = (await response.json()) as { result?: unknown };
  return { status: response.status, result: body.result };
}

test("AC1: POST /reverse returns the characters in reverse order", async () => {
  const { status, result } = await call("abc");
  assert.equal(status, 200);
  assert.deepEqual(result, "cba");
});

test("AC2: emoji and other astral characters stay intact", async () => {
  const { status, result } = await call("chef");
  assert.equal(status, 200);
  assert.deepEqual(result, "hagrak");
});

test("AC3: a value that is not a string is rejected with 400", async () => {
  const { status } = await call(42);
  assert.equal(status, 400);
});

