async function call(value: unknown): Promise<{ status: number; result: unknown }> {
  const app = createApp([feature], new MemoryStore());
  const response = await app(new Request("http://app.test/slug", { method: "POST", body: JSON.stringify({ value }), headers: { "content-type": "application/json" } }));
  const body = (await response.json()) as { result?: unknown };
  return { status: response.status, result: body.result };
}

test("AC1: POST /slug lowercases the value and joins words with dashes", async () => {
  const { status, result } = await call("Hello World");
  assert.equal(status, 200);
  assert.deepEqual(result, "hello-world");
});

test("AC2: runs of spaces become a single dash", async () => {
  const { status, result } = await call("Hello   World");
  assert.equal(status, 200);
  assert.deepEqual(result, "hello-world");
});

test("AC3: a value that is not a string is rejected with 400", async () => {
  const { status } = await call(42);
  assert.equal(status, 400);
});

